"""Real Chrome interaction checks and a retained screenshot, no simulated browser."""
import sys,html,json,re,subprocess,tempfile
from pathlib import Path
page=Path(sys.argv[1]).resolve();out=page.parent
link=re.search(r'id="plan-file" href="([^"]+)"',page.read_text())
if not link or not (out/link.group(1)).is_file():raise SystemExit('missing linked plan file')
script='''<script>try{let checks={rendered:document.body.dataset.rendered==='true',ten_routes:D.routes.length===10,initial_case:by('case').value===D.default_case};by('case').value='normal';refresh();const picture=()=>cv.toDataURL();let before=picture();by('time').value=route().base_seconds*.65;by('time').dispatchEvent(new Event('input'));checks.timeline=picture()!==before&&by('clock').textContent!=='0';before=picture();by('points').click();checks.points=picture()!==before;by('points').click();before=picture();by('detail').click();checks.original_scope=picture()!==before;by('detail').click();by('route').value=3;by('route').dispatchEvent(new Event('change'));checks.mow=route().zone==='B'&&by('stats').textContent.includes('规划足迹覆盖');before=picture();by('coverage').click();checks.coverage=picture()!==before;by('coverage').click();by('case').value='narrow';by('case').dispatchEvent(new Event('change'));checks.narrow=by('fault').textContent.includes('拒绝')&&D.faults.narrow.passed;by('case').value='stale';by('case').dispatchEvent(new Event('change'));checks.stale=by('fault').textContent.includes('PLAN_HASH_MISMATCH')&&by('fault').textContent.includes('STALE_INPUT_VERSION');by('case').value='original';by('case').dispatchEvent(new Event('change'));checks.infeasible=by('fault').textContent.includes('INFEASIBLE');by('case').value='normal';by('route').value=6;by('route').dispatchEvent(new Event('change'));checks.road=by('stats').textContent.includes('巡检转场');by('play').click();checks.play=playing;by('play').click();checks.pause=!playing;by('reset').click();checks.reset=Number(by('time').value)===0;checks.offline=document.body.textContent.includes('不是 Gazebo 实测')&&document.body.textContent.includes('NOT_CHECKED');checks.passed=Object.values(checks).every(Boolean);let p=document.createElement('pre');p.id='qa';p.textContent=JSON.stringify(checks);document.body.append(p);by('case').value='normal';by('route').value=3;refresh();by('time').value=route().base_seconds*.55;draw();}catch(e){let p=document.createElement('pre');p.id='qa';p.textContent=JSON.stringify({passed:false,error:String(e)});document.body.append(p);}</script>'''
with tempfile.TemporaryDirectory(prefix='s12_browser_') as tmp:
    p=out/'_qa.html';p.write_text(page.read_text().replace('</html>',script+'</html>'))
    args=['google-chrome','--headless','--disable-gpu','--no-first-run','--no-default-browser-check',f'--user-data-dir={tmp}/profile','--virtual-time-budget=1800','--window-size=1500,1640',f'--screenshot={out}/report_preview.png','--dump-dom',p.as_uri()]
    r=subprocess.run(args,capture_output=True,text=True,timeout=40);m=re.search('<pre id="qa">(.*?)</pre>',r.stdout)
    d=json.loads(html.unescape(m.group(1))) if m else {'passed':False,'error':'missing QA DOM','stderr':r.stderr[-1500:]};d.update(exit_code=r.returncode,command=args)
    (out/'browser_check.json').write_text(json.dumps(d,indent=2)+'\n');p.unlink(missing_ok=True);print(json.dumps(d));raise SystemExit(0 if d['passed'] and r.returncode==0 else 1)
